251	/** 位置で決まる引数の先頭から、サブコマンドの名前を探す。名前の語の数が多いものを優先する */
252	function findCommand(positionals: readonly string[]): { name: string; command: Command; rest: string[] } | undefined {
253	  for (let n = Math.min(2, positionals.length); n >= 1; n--) {
254	    const name = positionals.slice(0, n).join(" ");
255	    const command = COMMANDS[name];
256	    if (command !== undefined) return { name, command, rest: positionals.slice(n) };
257	  }
258	  return undefined;
259	}
