261	async function main(argv: readonly string[]): Promise<number> {
262	  let help: boolean;
263	  let positionals: string[];
264	  let pptxSkill: string | undefined;
265	  try {
266	    const parsed = parseArgs({
267	      args: [...argv],
268	      options: { help: { type: "boolean", short: "h" }, "pptx-skill": { type: "string" } },
269	      allowPositionals: true,
270	      strict: true,
271	    });
272	    help = parsed.values.help ?? false;
273	    positionals = parsed.positionals;
274	    pptxSkill = parsed.values["pptx-skill"];
275	  } catch (e) {
276	    process.stderr.write(`${e instanceof Error ? e.message : String(e)}\n\n${TOP_HELP}`);
277	    return 2;
278	  }
279	  const found = findCommand(positionals);
280	  if (found === undefined) {
281	    const name = positionals.join(" ");
282	    if (help && (name === "" || name === "setup")) {
283	      process.stdout.write(TOP_HELP);
284	      return 0;
285	    }
286	    process.stderr.write(`${name === "" ? "サブコマンドを指定する" : `存在しないサブコマンド: ${name}`}\n\n${TOP_HELP}`);
287	    return 2;
288	  }
289	  const { command } = found;
290	  if (help) {
291	    process.stdout.write(command.help);
292	    return 0;
293	  }
294	  try {
295	    return await command.run({ positionals: found.rest, pptxSkill });
296	  } catch (e) {
297	    if (e instanceof UsageError) {
298	      process.stderr.write(`${e.message}\n\n${command.help}`);
299	      return 2;
300	    }
301	    // 想定していない誤りも、終了コード 1 (検査の指摘あり) と区別できるよう、実行の誤り 2 にする
302	    const known = e instanceof SetupError || e instanceof ExecutionError;
303	    process.stderr.write(`${known ? e.message : e instanceof Error ? (e.stack ?? e.message) : String(e)}\n`);
304	    return 2;
305	  }
306	}
