113	 */
114	export function removePreviousPptx(deckDir: string): void {
115	  const dir = resolve(deckDir);
116	  if (!existsSync(dir) || !statSync(dir).isDirectory()) return;
117	  const pptxPath = join(dir, "build", "deck.pptx");
118	  try {
119	    rmSync(pptxPath, { force: true });
120	  } catch (e) {
121	    throw new ExecutionError(`前に書いた ${pptxPath} を消せない: ${e instanceof Error ? e.message : String(e)}`);
