127	 * 前に書いた build/deck.pptx は、最初に消す (ファイルがあることと、最後の実行が書いたことを一致させるため)。
128	 * テーマの色の書き込みが失敗したら、書いたファイルも消す。validate.py が形式の誤りを見つけたときは、調べられるようファイルを残す
129	 */
130	export async function buildPptx(deckDir: string, options: PptxOptions): Promise<PptxReport> {
131	  removePreviousPptx(deckDir);
132	  const env = options.env ?? process.env;
133	  const skill = pptxSkill(options.skillDir);
134	  const cache = installedCache(options);
135	  if (venvState(cache) !== "installed") {
136	    throw new ExecutionError(
137	      `ライブラリ (Python の venv) が、キャッシュのディレクトリ ${cache.venvDir} に入っていない。` +
138	        "サブコマンド setup status で状態を確認し、setup install で入れる",
139	    );
140	  }
141	  const paths = deckPaths(deckDir);
142	  const pptxPath = join(paths.buildDir, "deck.pptx");
143	  const themePath = join(paths.buildDir, "theme.json");
144	
145	  const check = await checkDeck(deckDir, options);
146	  if (check.deck === null) return { check, pptx: null, applyThemeOutput: "", validate: null };
147	
148	  writeFileSync(pptxPath, await renderPptx(check.deck, loadPptxGen(cache.nodeModulesDir)));
149	  writeFileSync(themePath, `${JSON.stringify(applyThemeInput(check.deck.theme), null, 2)}\n`);
150	  const applyTheme = options.applyTheme ?? skillApplyTheme(skill, cache, env);
151	  let applyThemeOutput: string;
152	  try {
153	    applyThemeOutput = applyTheme(pptxPath, themePath);
154	  } catch (e) {
155	    rmSync(pptxPath, { force: true });
156	    const message = e instanceof Error ? e.message : String(e);
157	    throw new ExecutionError(`${message}\nテーマの色を書き込めなかったので、PowerPoint のファイル ${pptxPath} は消した`);
